    {
        foreach (NarrativeOption option in MainlandChildhoodOptions.Shared)
            yield return option;

        yield return new NarrativeOption("northman_childhood_winter_games_option", new TextObject("{=bab_northman_childhood_winter_games_title}made games of the winter work."), new TextObject("{=bab_northman_childhood_winter_games_desc}You raced to stack firewood, carry feed, clear snow, and check traps before the cold drove everyone back to the hall."), (args, u) => u.UpgradeAthleticsCraftingSkills(args, DefaultCharacterAttributes.Endurance), ccm => IsNorthman(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_grit"));
        yield return new NarrativeOption("northman_childhood_godswood_option", new TextObject("{=bab_northman_childhood_godswood_title}listened to old tales in the godswood."), new TextObject("{=bab_northman_childhood_godswood_desc}Beneath the heart tree you heard the histories of the First Men, old oaths, guest right, and the duties binding a lord to the people of the North."), (args, u) => u.UpgradeLeadershipCharmSkills(args, DefaultCharacterAttributes.Social), ccm => IsNorthman(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_memory"));
        yield return new NarrativeOption("northman_childhood_raid_alarm_option", new TextObject("{=bab_northman_childhood_raid_alarm_title}learned what to do when the raid horn sounded."), new TextObject("{=bab_northman_childhood_raid_alarm_desc}Whether the danger came from sea, mountain, or forest, you learned to gather children and stores, carry warnings, and place a weapon in every capable hand."), (args, u) => u.UpgradeScoutingTacticsSkills(args, DefaultCharacterAttributes.Cunning), ccm => IsNorthman(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_tough"));
    }

