        yield return new NarrativeOption("northman_youth_winter_steward_option", new TextObject("{=bab_northman_youth_winter_steward_title}helped prepare a holding for winter."), new TextObject("{=bab_northman_youth_winter_steward_desc}You counted grain, fuel, fodder, preserved food, and warm beds, learning that a careless steward could doom a hall before spring."), (args, u) => u.UpgradeLeadershipStewardSkills(args, DefaultCharacterAttributes.Intelligence), ccm => IsNorthman(ccm) && (NarrativeChoiceState.ChildhoodWas("northman_childhood_winter_games_option", "childhood_smart_option") || NarrativeChoiceState.EducationWas("northman_education_winter_stores_option") || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Farmer || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.ArtisanUrban), ccm => SelectYouth(ccm, "guard", "act_childhood_book"));
