        yield return new NarrativeOption("northman_youth_wanderer_option", new TextObject("{=bab_northman_youth_wanderer_title}travelled with hunters and clan traders."), new TextObject("{=bab_northman_youth_wanderer_desc}You crossed long distances between lonely halls, learning the paths, customs, and grudges that maps and maesters rarely recorded."), (args, u) => u.UpgradeCharmScoutingSkills(args, DefaultCharacterAttributes.Cunning), ccm => IsNorthman(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Hunter || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.MerchantUrban || NarrativeChoiceState.ChildhoodWas("northman_childhood_godswood_option")), ccm => SelectYouth(ccm, "bandit", "act_childhood_fox"));
